package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.ZoneinfoVO;

class ZoneinfoValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of zoneinfo of user profile")
  void test_zoneinfo_value_holder_assign_plain_value() {
    Object holder = new Object();
    ZoneinfoValueHolder<Object> value = new ZoneinfoValueHolder<>(holder);
    Assertions.assertSame(holder, value.zoneinfo("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getZoneinfoValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getZoneinfo().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.zoneinfoNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getZoneinfoValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getZoneinfo().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of zoneinfo of user profile")
  void test_zoneinfo_value_holder_assign_value_object() {
    Object holder = new Object();
    ZoneinfoValueHolder<Object> value = new ZoneinfoValueHolder<>(holder);
    ZoneinfoVO vo = ZoneinfoVO.from("one");
    Assertions.assertFalse(value.getZoneinfoValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.zoneinfo(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getZoneinfoValue().orElseThrow());
    Assertions.assertSame(holder, value.zoneinfo(Optional.empty()));
    Assertions.assertFalse(value.getZoneinfoValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.zoneinfo(Optional.of(vo)));
    Assertions.assertSame(vo, value.getZoneinfoValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of zoneinfo of user profile against the original")
  void test_zoneinfo_value_holder_read() {
    Object holder = new Object();
    ZoneinfoValueHolder<Object> value = new ZoneinfoValueHolder<>(holder);
    ZoneinfoVO vo = ZoneinfoVO.from("one");
    ZoneinfoVO other = ZoneinfoVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getZoneinfoValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readZoneinfo(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readZoneinfo(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.zoneinfo(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readZoneinfo(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readZoneinfo(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of zoneinfo of user profile")
  void test_zoneinfo_value_holder_unset() {
    Object holder = new Object();
    ZoneinfoValueHolder<Object> value = new ZoneinfoValueHolder<>(holder);
    ZoneinfoVO vo = ZoneinfoVO.from("one");
    value.zoneinfo(vo);
    Assertions.assertSame(holder, value.unsetZoneinfoIfMatches("zoneinfo_other"));
    Assertions.assertTrue(value.getZoneinfoValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetZoneinfoIfMatches("zoneinfo"));
    Assertions.assertFalse(value.getZoneinfoValue().isPresent(),
        "The field name must clear the value");
    value.zoneinfo(vo);
    Assertions.assertSame(holder, value.unsetZoneinfo());
    Assertions.assertFalse(value.getZoneinfoValue().isPresent(), "Unset must clear the value");
  }
}
